import type { Locale } from "./locales";
import { withIdFallback } from "@/lib/locales";
import type { PricingModel } from "./pricing";

export type ModelPriceRow = {
  label: string;
  flatkey: string;
  official?: string;
  value?: string;
};

export type ModelGeneratorField = {
  name: string;
  label: string;
  type: "select" | "number" | "text" | "boolean";
  defaultValue: string | number | boolean;
  options?: string[];
  min?: number;
  max?: number;
  help?: string;
};

export type ModelGeneratorConfig = {
  kind: "image" | "video" | "audio";
  endpoint: string;
  storageKey: string;
  fields: ModelGeneratorField[];
};

export type ModelConfig = {
  slug: string;
  modelIds: string[];
  displayName: string;
  modelId: string;
  generator?: ModelGeneratorConfig;
  officialName: string;
  officialPrice: string;
  flatkeyPrice: string;
  estFlatkey: string;
  estOfficial: string;
  examplePrompt: string;
  priceUnit: ModelLandingKey;
  // Overrides the generic per-kind description on the model detail page. Set it
  // when a model's capabilities differ enough from its family that the shared
  // copy would be wrong (reference limits, frame control, audio behaviour).
  summary?: ModelLandingKey;
  rows: ModelPriceRow[];
  seo: {
    title: string;
    description: string;
  };
  positioning: ModelLandingKey;
  useCases: ModelLandingKey[];
  faq: Array<{ question: ModelLandingKey; answer: ModelLandingKey }>;
};

