    "Is the Flatkey API OpenAI-compatible?": "Flatkey API 兼容 OpenAI 吗？",
    "Yes. Point base_url at Flatkey and keep your existing OpenAI SDK, request shapes, and streaming code.": "兼容。把 base_url 指向 Flatkey，现有的 OpenAI SDK、请求结构和流式代码都不用改。",
    "How does billing work?": "计费是怎么算的？",
    "One balance covers every model — text, image, video, and audio. You are charged per request against live catalog pricing, with usage analytics and a single invoice.": "一个余额覆盖全部模型 —— 文本、图片、视频和音频。按请求依照实时目录价扣费，并提供用量分析和统一账单。",
    "Are there rate limits?": "有速率限制吗？",
