    "What happens to my prompts and generated files?": "我的提示词和生成的文件会怎么处理？",
    "Requests are relayed to the upstream provider for the model you choose. Generated media is served through Flatkey so your keys and the upstream endpoint stay private.": "请求会中继到你所选模型的上游供应商。生成的媒体通过 Flatkey 代理返回，你的密钥和上游地址不会外泄。",
