    "Connect your coding agent with one command, then use Flatkey from your existing projects.": "Conecta tu agente de código con un comando y usa Flatkey desde tus proyectos actuales.",
    "Ready-to-run example for {{model}}": "Ejemplo listo para ejecutar de {{model}}",
    "Is the Flatkey API OpenAI-compatible?": "¿La API de Flatkey es compatible con OpenAI?",
    "Yes. Point base_url at Flatkey and keep your existing OpenAI SDK, request shapes, and streaming code.": "Sí. Apunta base_url a Flatkey y conserva tu SDK de OpenAI, las mismas peticiones y tu código de streaming.",
    "How does billing work?": "¿Cómo funciona la facturación?",
    "One balance covers every model — text, image, video, and audio. You are charged per request against live catalog pricing, with usage analytics and a single invoice.": "Un solo saldo cubre todos los modelos: texto, imagen, video y audio. Se cobra por petición según el precio vigente del catálogo, con analítica de uso y una única factura.",
    "Are there rate limits?": "¿Hay límites de tasa?",
    "Limits are per account and scale with your plan. Request routing spreads traffic across available upstream channels for the model.": "Los límites son por cuenta y crecen con tu plan. El enrutado reparte el tráfico entre los canales upstream disponibles para el modelo.",
    "What happens to my prompts and generated files?": "¿Qué pasa con mis prompts y archivos generados?",
    "Requests are relayed to the upstream provider for the model you choose. Generated media is served through Flatkey so your keys and the upstream endpoint stay private.": "Las peticiones se retransmiten al proveedor upstream del modelo elegido. El contenido generado se sirve a través de Flatkey, así tus claves y el endpoint upstream permanecen privados.",
