    "How does billing work?": "Как устроена оплата?",
    "One balance covers every model — text, image, video, and audio. You are charged per request against live catalog pricing, with usage analytics and a single invoice.": "Один баланс покрывает все модели: текст, изображения, видео и аудио. Списание идёт за запрос по актуальной цене каталога, с аналитикой использования и единым счётом.",
    "Are there rate limits?": "Есть ли ограничения по скорости?",
    "Limits are per account and scale with your plan. Request routing spreads traffic across available upstream channels for the model.": "Лимиты действуют на аккаунт и растут вместе с планом. Маршрутизация распределяет трафик по доступным upstream-каналам модели.",
    "What happens to my prompts and generated files?": "Что происходит с моими промптами и созданными файлами?",
    "Requests are relayed to the upstream provider for the model you choose. Generated media is served through Flatkey so your keys and the upstream endpoint stay private.": "Запросы ретранслируются провайдеру выбранной модели. Созданные медиа отдаются через Flatkey, поэтому ваши ключи и адрес upstream остаются приватными.",
