    "Create an API key": "Создайте API-ключ",
    "Sign up and generate a key in the console. No credit card to start.": "Зарегистрируйтесь и создайте ключ в консоли. Карта не нужна.",
    "Point your SDK at Flatkey": "Направьте SDK на Flatkey",
