    "Paste the next line into your terminal to integrate Flatkey in seconds.": "次の行をターミナルに貼り付けると、数秒で Flatkey を組み込めます。",
    "Daily {{model}} requests on Flatkey": "Flatkey における {{model}} の日次リクエスト数",
