    "All four options use the same account and model catalog.": "4 つの方法はすべて同じアカウントとモデルカタログを使います。",
    "API for developers": "開発者向け API",
    "Call any model with an OpenAI-compatible API. Copy a ready-to-run example for your model and language.": "OpenAI 互換 API であらゆるモデルを呼び出せます。モデルと言語に合わせてすぐ実行できる例をコピーできます。",
    "SDKs for developers": "開発者向け SDK",
    "Use the OpenAI SDK you already know — with Flatkey as the gateway.": "使い慣れた OpenAI SDK をそのまま — ゲートウェイに Flatkey を使うだけです。",
    "Flatkey CLI": "Flatkey CLI",
    "Generate images and videos from your terminal. Let your AI assistant drive the workflow.": "ターミナルから画像と動画を生成します。ワークフローは AI アシスタントに任せられます。",
    "Codex & Claude Code": "Codex と Claude Code",
    "Connect your coding agent with one command, then use Flatkey from your existing projects.": "コーディングエージェントをコマンド 1 つで接続し、既存プロジェクトから Flatkey を使えます。",
    "Ready-to-run example for {{model}}": "{{model}} のすぐ実行できる例",
    "Is the Flatkey API OpenAI-compatible?": "Flatkey API は OpenAI 互換ですか？",
    "Yes. Point base_url at Flatkey and keep your existing OpenAI SDK, request shapes, and streaming code.": "互換です。base_url を Flatkey に向けるだけで、既存の OpenAI SDK・リクエスト形式・ストリーミング処理はそのまま動きます。",
    "How does billing work?": "課金はどうなりますか？",
    "One balance covers every model — text, image, video, and audio. You are charged per request against live catalog pricing, with usage analytics and a single invoice.": "1 つの残高でテキスト・画像・動画・音声のすべてのモデルをカバーします。カタログの実時間価格に基づきリクエスト単位で課金され、利用分析と一括請求が付きます。",
    "Are there rate limits?": "レート制限はありますか？",
    "Limits are per account and scale with your plan. Request routing spreads traffic across available upstream channels for the model.": "制限はアカウント単位で、プランに応じて拡大します。リクエストはそのモデルで利用可能な上流チャネルに分散されます。",
    "What happens to my prompts and generated files?": "プロンプトや生成ファイルはどう扱われますか？",
    "Requests are relayed to the upstream provider for the model you choose. Generated media is served through Flatkey so your keys and the upstream endpoint stay private.": "リクエストは選択したモデルの上流プロバイダーに中継されます。生成された媒体は Flatkey 経由で配信されるため、キーと上流エンドポイントは公開されません。",
    "Quick Start": "クイックスタート",
    "Where {{model}} sits in Flatkey traffic": "Flatkey トラフィックにおける {{model}} の位置",
    "Rank": "順位",
    "Monthly tokens": "今月のトークン数",
    "Start calling {{model}} in three steps": "3 ステップで {{model}} を呼び出す",
    "All options use the same account and model catalog.": "どの方法も同じアカウントとモデルカタログを使います。",
    "Create an API key": "API キーを作成",
    "Sign up and generate a key in the console. No credit card to start.": "登録してコンソールでキーを発行します。クレジットカードは不要です。",
    "Point your SDK at Flatkey": "SDK の向き先を Flatkey に",
    "Change base_url and api_key. The OpenAI SDK you already use keeps working.": "base_url と api_key を変更するだけで、既存の OpenAI SDK がそのまま動きます。",
    "Send your first request": "最初のリクエストを送る",
