    "API for developers": "API cho lập trình viên",
    "Call any model with an OpenAI-compatible API. Copy a ready-to-run example for your model and language.": "Gọi mọi mô hình bằng API tương thích OpenAI. Sao chép ví dụ chạy được ngay theo mô hình và ngôn ngữ của bạn.",
    "SDKs for developers": "SDK cho lập trình viên",
