    "Codex & Claude Code": "Codex và Claude Code",
    "Connect your coding agent with one command, then use Flatkey from your existing projects.": "Kết nối agent lập trình bằng một lệnh, rồi dùng Flatkey từ các dự án hiện có.",
    "Ready-to-run example for {{model}}": "Ví dụ chạy được ngay cho {{model}}",
    "Is the Flatkey API OpenAI-compatible?": "API của Flatkey có tương thích OpenAI không?",
    "Yes. Point base_url at Flatkey and keep your existing OpenAI SDK, request shapes, and streaming code.": "Có. Trỏ base_url sang Flatkey và giữ nguyên SDK OpenAI, cấu trúc yêu cầu và mã streaming hiện tại.",
    "How does billing work?": "Cách tính phí thế nào?",
    "One balance covers every model — text, image, video, and audio. You are charged per request against live catalog pricing, with usage analytics and a single invoice.": "Một số dư dùng cho mọi mô hình: văn bản, ảnh, video và âm thanh. Tính phí theo từng yêu cầu dựa trên giá danh mục thời gian thực, kèm phân tích mức dùng và một hóa đơn duy nhất.",
    "Are there rate limits?": "Có giới hạn tốc độ không?",
    "Limits are per account and scale with your plan. Request routing spreads traffic across available upstream channels for the model.": "Giới hạn tính theo tài khoản và tăng theo gói. Bộ định tuyến phân phối lưu lượng qua các kênh upstream khả dụng của mô hình.",
    "What happens to my prompts and generated files?": "Prompt và tệp tạo ra của tôi được xử lý thế nào?",
    "Requests are relayed to the upstream provider for the model you choose. Generated media is served through Flatkey so your keys and the upstream endpoint stay private.": "Yêu cầu được chuyển tiếp tới nhà cung cấp upstream của mô hình bạn chọn. Nội dung tạo ra được phục vụ qua Flatkey nên khóa và endpoint upstream của bạn vẫn riêng tư.",
    "Quick Start": "Bắt đầu nhanh",
