    "{{model}} is an audio workflow model for video-to-music, narration, sound beds, and synchronized output variants. Configure duration, format, speech preservation, and output count before opening the console.": "{{model}} は動画から音楽、ナレーション、サウンドベッド、同期した出力バリエーション向けの音声ワークフローモデルです。コンソールを開く前に、長さ、形式、音声保持、出力数を設定できます。",
    "Prepare an audio request for {{model}} here. The console receives prompt, timing, format, source URL, and variant settings after authentication.": "ここで {{model}} の音声リクエストを準備します。認証後、コンソールが prompt、タイミング、形式、元 URL、バリエーション設定を受け取ります。",
