    "Open the console with {{model}} selected. The prompt and request draft are preserved after sign-up or login without placing full content in the URL.": "{{model}} を選択した状態でコンソールを開きます。登録またはログイン後も prompt とリクエスト下書きは保持され、完全な内容を URL に置きません。",
